import type { IAuthModuleService, MedusaContainer } from "@medusajs/framework/types"
import { ContainerRegistrationKeys, Modules } from "@medusajs/framework/utils"
import { likeLiteral } from "../../../lib/db/like"

type Container = Pick<MedusaContainer, "resolve">

type Metadata = Record<string, unknown> | null | undefined

/**
 * What Medusa's auth service does beyond its published interface (2.21.2,
 * generated by MedusaService): the address confirmations.
 */
interface AuthVerifications {
  listAuthVerifications: (
    filters: Record<string, unknown>,
    config: { select: string[]; take: null }
  ) => Promise<{ id: string }[]>
  deleteAuthVerifications: (ids: string[]) => Promise<void>
}

/** The customer's sign-ins: every identity pointing at them, e-mail and social alike. */
export async function signInsOf(container: Container, customerId: string): Promise<string[]> {
  const { data } = await container.resolve(ContainerRegistrationKeys.QUERY).graph({
    entity: "auth_identity",
    fields: ["id", "app_metadata"],
    filters: { app_metadata: { customer_id: customerId } },
  })
  return (data as { id: string; app_metadata?: Metadata }[])
    .filter((identity) => identity.app_metadata?.["customer_id"] === customerId)
    .map((identity) => identity.id)
}

/** Another actor on the identity (a staff member's `user_id`): what keeps it. */
const otherActor = (metadata: Metadata) =>
  Object.entries(metadata ?? {}).some(
    ([key, value]) => key !== "customer_id" && key.endsWith("_id") && value !== null
  )

/**
 * The customer's sign-ins after their record is closed (adr/0041 §6;
 * security review of PR #73, L4a). Medusa's `removeCustomerAccountWorkflow`
 * handles only the first identity it finds, and keeps one whose metadata
 * holds anything else, our password change time included, with its login
 * address. Here every identity of the customer goes, with its logins and
 * confirmations (the auth module deletes them with it), unless another
 * actor signs in with it: that one only stops naming the customer. The
 * address confirmations asked for the address by any identity go too.
 */
export async function eraseSignIns(
  container: Container,
  identityIds: string[],
  email: string | null
): Promise<void> {
  const auth = container.resolve<IAuthModuleService>(Modules.AUTH)
  if (identityIds.length > 0) {
    const left = await auth.listAuthIdentities(
      { id: identityIds },
      { select: ["id", "app_metadata"], take: null }
    )
    const gone = left.filter((identity) => !otherActor(identity.app_metadata))
    if (gone.length > 0) {
      await auth.deleteAuthIdentities(gone.map((identity) => identity.id))
    }
    for (const kept of left.filter((identity) => otherActor(identity.app_metadata))) {
      await auth.updateAuthIdentities({
        id: kept.id,
        app_metadata: { ...(kept.app_metadata ?? {}), customer_id: null },
      })
    }
  }
  if (email) {
    const verifications = auth as unknown as AuthVerifications
    const rows = await verifications.listAuthVerifications(
      { entity_id: { $ilike: likeLiteral(email) } },
      { select: ["id"], take: null }
    )
    if (rows.length > 0) {
      await verifications.deleteAuthVerifications(rows.map((row) => row.id))
    }
  }
}
